  "tips": [
   "Das Backpulver ist der Trick für die extra-krosse Kruste – Ankochen nicht auslassen.",
   "Wer es milder mag, reduziert den Cayennepfeffer; wer es rauchiger mag, erhöht den Anteil an geräuchertem Paprikapulver.",
   "Ein Klecks Joghurt oder Sauerrahm dazu ist eine spannende, kühlende Ergänzung, da Paprika und Joghurt gemeinsame grün-blumige Aromanoten teilen."
  ],
